(()=>{const App={$:{scrollToRevealArray:document.querySelectorAll(".scroll-to-reveal"),ctaBtn:document.querySelector(".cta"),mobileList:document.querySelector(".mobile-list"),navIcon:document.querySelector(".nav--icon"),btns:document.querySelectorAll(".js-btn"),sections:document.querySelectorAll(".js-section"),getTimeAgoItems:()=>document.querySelectorAll(".time-ago"),},initTinySlider:()=>{const slider=tns({container:".slide__container",arrowKeys:!0,loop:!1,rewind:!1,mode:"gallery",controlsText:[`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 512" width="16" height="16">
            <path d="M31.7 239l136-136c9.4-9.4 24.6-9.4 33.9 0l22.6 22.6c9.4 9.4 9.4 24.6 0 33.9L127.9 256l96.4 96.4c9.4 9.4 9.4 24.6 0 33.9L201.7 409c-9.4 9.4-24.6 9.4-33.9 0l-136-136c-9.5-9.4-9.5-24.6-.1-34z"/>
          </svg>`,`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 512" width="16" height="16">
            <path d="M224.3 273l-136 136c-9.4 9.4-24.6 9.4-33.9 0l-22.6-22.6c-9.4-9.4-9.4-24.6 0-33.9l96.4-96.4-96.4-96.4c-9.4-9.4-9.4-24.6 0-33.9L54.3 103c9.4-9.4 24.6-9.4 33.9 0l136 136c9.5 9.4 9.5 24.6.1 34z"/>
          </svg>`,],nav:!1,});setTimeout(()=>{document.querySelector('[data-controls="prev"]')?.setAttribute("aria-label","Testimonio anterior");document.querySelector('[data-controls="next"]')?.setAttribute("aria-label","Siguiente testimonio")},100);slider.events.on("transitionEnd",()=>{App.calcTimeAgo()})},timeAgo(dateString){const date=new Date(dateString);const now=new Date();const seconds=Math.floor((now-date)/1000);const intervals=[{label:"year",seconds:31536000},{label:"month",seconds:2592000},{label:"day",seconds:86400},{label:"hour",seconds:3600},{label:"minute",seconds:60}];for(const interval of intervals){const count=Math.floor(seconds/interval.seconds);if(count>=1){return `${count} ${interval.label}${count > 1 ? "s" : ""} ago`}}
return"Just now"},calcTimeAgo:()=>{const items=App.$.getTimeAgoItems();if(items.length){for(let i=0;i<items.length;i++){const date=items[i].getAttribute("data-date");items[i].textContent=timeAgo(date)}}},setActiveLink:(event,buttons)=>{for(var i=0;i<buttons.length;i++){buttons[i].classList.remove("selected")}
event.target.classList.add("selected")},smoothScrollTo:(i,buttons,event)=>{const sections=App.$.sections;var element=sections[i-1]||sections[i-8];App.setActiveLink(event,buttons);if(App.$.mobileList.classList.contains("show")){App.$.mobileList.classList.toggle("show")}
window.scrollTo({behavior:"smooth",top:element?element.offsetTop-100:0,left:0,})},initScrollToReveal:()=>{const scrollToRevealArray=App.$.scrollToRevealArray;for(var i=0;i<scrollToRevealArray.length;i++){new Waypoint({element:scrollToRevealArray[i],handler:function(direction){this.element.classList.add("fadeInUp")},offset:Waypoint.viewportHeight(),})}},initScrollToRevealNav:()=>{new Waypoint({element:App.$.ctaBtn,handler:function(direction){if(direction==="down"){document.querySelector("nav").classList.add("fixed")}else{document.querySelector("nav").classList.remove("fixed")}},offset:-80,})},attachBtsForSmoothScroll:()=>{const btns=App.$.btns;const sections=App.$.sections;if(btns.length&&sections.length>0){for(var i=0;i<btns.length;i++){btns[i].addEventListener("click",App.smoothScrollTo.bind(this,i,btns))}}},listenerNavIcon:()=>{const navIcon=App.$.navIcon;navIcon.addEventListener("click",function(){document.querySelector(".mobile-list").classList.toggle("show")})},stats:{getWeeksArray:()=>{var weekArray=[];for(var i=0;i<30;i++){weekArray.push("3/"+i)}
return weekArray},getGeneratedLineData:(numbers)=>{return{labels:App.stats.getWeeksArray(),datasets:[{borderColor:"rgba(174,155,255,0.67)",pointColor:"#AE9BFF",data:numbers,pointRadius:4,borderWidth:1,pointBackgroundColor:"#C0B2FC",},],}},getGeneratedBarData:(numbers)=>{var labels=App.stats.getWeeksArray();return{labels:App.stats.getWeeksArray(),datasets:[{labels:labels,backgroundColor:"rgba(174,155,255,0.67)",data:numbers,},],}},randomArray:(length,max)=>{return Array.apply(null,Array(length)).map(function(){return Math.round(Math.random()*max)})},},generateCharts:()=>{for(var i=0;i<6;i++){var ctx=document.getElementById("stats-"+i).getContext("2d");var type,dataType;if(i!==1&&i!==4){type="line";dataType=App.stats.getGeneratedLineData(App.stats.randomArray(30,1000))}else{type="bar";dataType=App.stats.getGeneratedBarData(App.stats.randomArray(30,1000))}
new Chart(ctx,{type:type,data:dataType,scaleShowVerticalLines:!1,scaleGridLineColor:"black",options:{responsive:!0,maintainAspectRatio:!1,elements:{line:{tension:0,},},legend:{display:!1,},scales:{yAxes:[{ticks:{fontColor:"#444363",fontSize:12,},},],xAxes:[{ticks:{fontColor:"#444363",fontSize:12,},},],},},})}},init(){App.generateCharts();App.initTinySlider();App.initScrollToReveal();App.initScrollToRevealNav();App.attachBtsForSmoothScroll();App.listenerNavIcon()},};App.init()})()